import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../services/firebaseConfig";
import {
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  Tooltip,
  Legend,
  XAxis,
  ResponsiveContainer,
} from "recharts";

export default function Dashboard() {
  const [transactions, setTransactions] = useState([]);
  const [fixedExpenses, setFixedExpenses] = useState([]);
  const [categories, setCategories] = useState([]);
  const [summary, setSummary] = useState({ entradas: 0, saidas: 0, saldo: 0, gastosFixos: 0 });

  useEffect(() => {
    const loadData = async () => {
      try {
        // Carregar transações
        const transSnapshot = await getDocs(collection(db, "transactions"));
        const transData = transSnapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));

        console.log("🔥 Dados do Firestore (Transações):", transData);

        setTransactions(transData);

        // Carregar gastos fixos
        const fixedSnapshot = await getDocs(collection(db, "fixed_expenses"));
        const fixedData = fixedSnapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));

        console.log("🔥 Dados do Firestore (Gastos Fixos):", fixedData);

        setFixedExpenses(fixedData);

        // Carregar categorias
        const catSnapshot = await getDocs(collection(db, "categories"));
        const catData = catSnapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));

        console.log("🔥 Dados do Firestore (Categorias):", catData);

        setCategories(catData);

        // Calcular totais
        const entradas = transData
          .filter(
            (t) =>
              (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === "entrada"
          )
          .reduce((acc, t) => acc + parseFloat(t.value || 0), 0);

        const saidas = transData
          .filter(
            (t) =>
              (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === "saída"
          )
          .reduce((acc, t) => acc + parseFloat(t.value || 0), 0);

        const gastosFixos = fixedData.reduce((acc, f) => acc + parseFloat(f.value || 0), 0);

        console.log("✅ Entradas:", entradas, "Saídas:", saidas, "Gastos Fixos:", gastosFixos);

        setSummary({ entradas, saidas, saldo: entradas - saidas - gastosFixos, gastosFixos });
      } catch (error) {
        console.error("Erro ao carregar dados:", error);
      }
    };

    loadData();
  }, []);

  const getColorForCategory = (categoryName) => {
    const category = categories.find(cat => cat.name === categoryName);
    return category ? category.color : "#8884d8"; // Cor padrão se não encontrar
  };

  const expenseMap = {};
  transactions
    .filter((t) => (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === "saída")
    .forEach((t) => {
      const cat = t.category || "Sem categoria";
      if (!expenseMap[cat]) expenseMap[cat] = 0;
      expenseMap[cat] += parseFloat(t.value || 0);
    });
  const expenseDetails = Object.entries(expenseMap).map(([name, value]) => ({
    name,
    value,
    color: getColorForCategory(name, "expense"),
  }));

  const incomeMap = {};
  transactions
    .filter((t) => (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === "entrada")
    .forEach((t) => {
      const cat = t.category || "Sem categoria";
      if (!incomeMap[cat]) incomeMap[cat] = 0;
      incomeMap[cat] += parseFloat(t.value || 0);
    });
  const incomeDetails = Object.entries(incomeMap).map(([name, value]) => ({
    name,
    value,
    color: getColorForCategory(name, "income"),
  }));

  const fixedColors = ["#3b82f6", "#f59e0b", "#10b981", "#ef4444", "#8b5cf6"];

  const barData = [
    { name: "Entradas", valor: summary.entradas },
    { name: "Saídas", valor: summary.saidas },
    { name: "Gastos Fixos", valor: summary.gastosFixos },
  ];

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6 }}
      className="p-6 text-white"
    >
      <motion.h2
        initial={{ opacity: 0, x: -20 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ delay: 0.2 }}
        className="text-3xl font-bold mb-6 text-center"
      >
        🚀 Dashboard Financeiro
      </motion.h2>

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.4 }}
        className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8"
      >
        <motion.div
          whileHover={{ scale: 1.05 }}
          className="bg-gradient-to-br from-green-600 to-green-800 p-6 rounded-xl shadow-lg border border-green-500/20"
        >
          <div className="text-green-200 text-sm font-medium">Entradas</div>
          <div className="text-2xl font-bold text-white mt-1">
            R$ {summary.entradas.toFixed(2)}
          </div>
        </motion.div>
        <motion.div
          whileHover={{ scale: 1.05 }}
          className="bg-gradient-to-br from-red-600 to-red-800 p-6 rounded-xl shadow-lg border border-red-500/20"
        >
          <div className="text-red-200 text-sm font-medium">Saídas</div>
          <div className="text-2xl font-bold text-white mt-1">
            R$ {summary.saidas.toFixed(2)}
          </div>
        </motion.div>
        <motion.div
          whileHover={{ scale: 1.05 }}
          className="bg-gradient-to-br from-blue-600 to-blue-800 p-6 rounded-xl shadow-lg border border-blue-500/20"
        >
          <div className="text-blue-200 text-sm font-medium">Gastos Fixos</div>
          <div className="text-2xl font-bold text-white mt-1">
            R$ {summary.gastosFixos.toFixed(2)}
          </div>
        </motion.div>
        <motion.div
          whileHover={{ scale: 1.05 }}
          className={`p-6 rounded-xl shadow-lg border ${summary.saldo >= 0
              ? "bg-gradient-to-br from-emerald-600 to-emerald-800 border-emerald-500/20"
              : "bg-gradient-to-br from-red-700 to-red-900 border-red-600/20"
            }`}
        >
          <div className={`text-sm font-medium ${summary.saldo >= 0 ? "text-emerald-200" : "text-red-200"
            }`}>
            Saldo
          </div>
          <div className="text-2xl font-bold text-white mt-1">
            R$ {summary.saldo.toFixed(2)}
          </div>
        </motion.div>
      </motion.div>

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.6 }}
        className="grid grid-cols-1 lg:grid-cols-2 gap-6"
      >
        {/* Gráfico de Barras */}
        <motion.div
          whileHover={{ scale: 1.02 }}
          className="bg-gradient-to-br from-gray-800 to-gray-900 p-6 rounded-xl shadow-xl border border-gray-700/50"
        >
          <h3 className="text-xl font-semibold mb-4 text-center text-gray-200">
            📈 Resumo Geral
          </h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={barData}>
              <XAxis dataKey="name" tick={{ fill: "#cbd5e1", fontSize: 12 }} />
              <Tooltip
                cursor={{ fill: "rgba(56, 189, 248, 0.1)" }}
                contentStyle={{
                  background: "#1e293b",
                  border: "1px solid #38bdf8",
                  borderRadius: "8px",
                  color: "#f8fafc"
                }}
              />
              <Bar dataKey="valor" radius={[8, 8, 0, 0]}>
                {barData.map((entry, index) => (
                  <Cell
                    key={`bar-${index}`}
                    fill={index === 0 ? "#22c55e" : index === 1 ? "#ef4444" : "#3b82f6"}
                  />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </motion.div>

        {/* Gráfico de Pizza - Saídas */}
        <motion.div
          whileHover={{ scale: 1.02 }}
          className="bg-gradient-to-br from-gray-800 to-gray-900 p-6 rounded-xl shadow-xl border border-gray-700/50"
        >
          <h3 className="text-xl font-semibold mb-4 text-center text-gray-200">
            📊 Saídas por Categoria
          </h3>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={expenseDetails}
                dataKey="value"
                nameKey="name"
                outerRadius={100}
                animationBegin={0}
                animationDuration={800}
              >
                {expenseDetails.map((entry, index) => (
                  <Cell key={`slice-${index}`} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip
                contentStyle={{
                  background: "#1e293b",
                  border: "1px solid #38bdf8",
                  borderRadius: "8px",
                  color: "#f8fafc"
                }}
              />
              <Legend
                wrapperStyle={{ color: "#cbd5e1", fontSize: "12px" }}
              />
            </PieChart>
          </ResponsiveContainer>
        </motion.div>

        {/* Gráfico de Pizza - Entradas */}
        <motion.div
          whileHover={{ scale: 1.02 }}
          className="bg-gradient-to-br from-gray-800 to-gray-900 p-6 rounded-xl shadow-xl border border-gray-700/50"
        >
          <h3 className="text-xl font-semibold mb-4 text-center text-gray-200">
            💰 Entradas por Categoria
          </h3>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={incomeDetails}
                dataKey="value"
                nameKey="name"
                outerRadius={100}
                animationBegin={0}
                animationDuration={800}
              >
                {incomeDetails.map((entry, index) => (
                  <Cell key={`slice-${index}`} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip
                contentStyle={{
                  background: "#1e293b",
                  border: "1px solid #38bdf8",
                  borderRadius: "8px",
                  color: "#f8fafc"
                }}
              />
              <Legend
                wrapperStyle={{ color: "#cbd5e1", fontSize: "12px" }}
              />
            </PieChart>
          </ResponsiveContainer>
        </motion.div>

        {/* Gráfico de Pizza - Gastos Fixos */}
        <motion.div
          whileHover={{ scale: 1.02 }}
          className="bg-gradient-to-br from-gray-800 to-gray-900 p-6 rounded-xl shadow-xl border border-gray-700/50"
        >
          <h3 className="text-xl font-semibold mb-4 text-center text-gray-200">
            🏠 Gastos Fixos
          </h3>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={fixedExpenses.map((f) => ({ name: f.name, value: parseFloat(f.value || 0) }))}
                dataKey="value"
                nameKey="name"
                outerRadius={100}
                animationBegin={0}
                animationDuration={800}
              >
                {fixedExpenses.map((entry, index) => (
                  <Cell key={`slice-${index}`} fill={fixedColors[index % fixedColors.length]} />
                ))}
              </Pie>
              <Tooltip
                contentStyle={{
                  background: "#1e293b",
                  border: "1px solid #38bdf8",
                  borderRadius: "8px",
                  color: "#f8fafc"
                }}
              />
              <Legend
                wrapperStyle={{ color: "#cbd5e1", fontSize: "12px" }}
              />
            </PieChart>
          </ResponsiveContainer>
        </motion.div>
      </motion.div>
    </motion.div>
  );
}
